using System.Text.RegularExpressions;

var input = Console.In.ReadToEnd().Replace("\r\n", "\n");
var newlineIndex = input.IndexOf('\n');
var definesLine = newlineIndex < 0 ? input : input[..newlineIndex];
var rest = newlineIndex < 0 ? "" : input[(newlineIndex + 1)..];
var defines = definesLine.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToHashSet();
var sourceLines = rest.Split('\n');
if (sourceLines.Length > 0 && sourceLines[^1].Length == 0) sourceLines = sourceLines[..^1];

var output = new List<string>();
var branches = new List<bool>();
var error = false;
bool IsActive() => branches.All(active => active);

foreach (var raw in sourceLines)
{
    var line = raw.Trim();
    var isIf = line == "#if" || line.StartsWith("#if ", StringComparison.Ordinal);
    if (isIf)
    {
        var symbol = line[3..].Trim();
        if (symbol.Length == 0 || !Regex.IsMatch(symbol, "^[A-Za-z_][A-Za-z0-9_]*$"))
        {
            error = true;
            break;
        }
        branches.Add(defines.Contains(symbol));
        continue;
    }
    if (line == "#else")
    {
        if (branches.Count == 0) { error = true; break; }
        branches[^1] = !branches[^1];
        continue;
    }
    if (line == "#endif")
    {
        if (branches.Count == 0) { error = true; break; }
        branches.RemoveAt(branches.Count - 1);
        continue;
    }
    if (line == "#region" || line.StartsWith("#region ", StringComparison.Ordinal)
        || line == "#endregion" || line.StartsWith("#endregion ", StringComparison.Ordinal)) continue;
    if (IsActive()) output.Add(raw);
}

if (error || branches.Count > 0) Environment.Exit(1);
var builder = new System.Text.StringBuilder();
foreach (var line in output) builder.Append(line).Append('\n');
Console.Write(builder.ToString());
